ptions":[{"content":"$Z = 0 \\text{ at the origin}$","displayOrder":0,"isCorrect":true,"optionKey":"A"},{"content":"$\\text{the maximum of } Z \\text{ is } 24$","displayOrder":1,"isCorrect":true,"optionKey":"B"},{"content":"$\\text{the maximum of } Z \\text{ is } 12$","displayOrder":2,"isCorrect":false,"optionKey":"C"},{"content":"$Z = 4 \\text{ at the origin}$","displayOrder":3,"isCorrect":false,"optionKey":"D"}],"questionContent":"Maximise $Z = 3x + 4y$ over the region with corner points $(0,0)$, $(4,0)$, $(4,3)$, $(0,3)$.\n\nWhich of the following are correct?","questionType":"MULTIPLE_CORRECT","solutionContent":"$Z$ is evaluated at each corner; the maximum is $24$ at $(4,3)$. At the origin $Z = 0$.","status":"PUBLISHED"}],"subjectName":"Mathematics"}$seedjson$::jsonb;
    subject_id_v  bigint;
    chapter_row   jsonb;
    question_row  jsonb;
    option_row    jsonb;
    chapter_id_v  bigint;
    question_id_v bigint;
    inserted_q    integer := 0;
    inserted_c    integer := 0;
BEGIN
    SELECT id INTO subject_id_v FROM subjects WHERE code = 'MATH';
    IF subject_id_v IS NULL THEN
        RAISE EXCEPTION 'Mathematics subject is missing; V2 must run before this migration';
    END IF;

    -- Chapters first, and idempotently: on a database where these were already created by hand
    -- a plain INSERT would fail the (subject_id, name) unique constraint.
    FOR chapter_row IN SELECT * FROM jsonb_array_elements(content -> 'chapters') LOOP
        INSERT INTO chapters (subject_id, name, description, active, display_order)
        VALUES (subject_id_v,
                chapter_row ->> 'name',
                chapter_row ->> 'description',
                TRUE,
                COALESCE((chapter_row ->> 'displayOrder')::int, 0))
        ON CONFLICT (subject_id, name) DO NOTHING;
        IF FOUND THEN
            inserted_c := inserted_c + 1;
        END IF;
    END LOOP;

    FOR question_row IN SELECT * FROM jsonb_array_elements(content -> 'questions') LOOP
        SELECT id INTO chapter_id_v
        FROM chapters
        WHERE subject_id = subject_id_v AND name = question_row ->> 'chapterName';

        IF chapter_id_v IS NULL THEN
            RAISE EXCEPTION 'Question references unknown chapter: %',
                            question_row ->> 'chapterName';
        END IF;

        INSERT INTO questions (subject_id, chapter_id, exam_pattern, difficulty, question_type,
                               question_content, solution_content, status, published_at)
        VALUES (subject_id_v,
                chapter_id_v,
                question_row ->> 'examPattern',
                question_row ->> 'difficulty',
                question_row ->> 'questionType',
                question_row ->> 'questionContent',
                question_row ->> 'solutionContent',
                COALESCE(question_row ->> 'status', 'PUBLISHED'),
                now())
        RETURNING id INTO question_id_v;

        FOR option_row IN SELECT * FROM jsonb_array_elements(question_row -> 'options') LOOP
            INSERT INTO question_options (question_id, option_key, content,
                                          display_order, is_correct)
            VALUES (question_id_v,
                    option_row ->> 'optionKey',
                    option_row ->> 'content',
                    COALESCE((option_row ->> 'displayOrder')::int, 0),
                    COALESCE((option_row ->> 'isCorrect')::boolean, FALSE));
        END LOOP;

        inserted_q := inserted_q + 1;
    END LOOP;

    RAISE NOTICE 'Seeded % chapter(s) and % question(s)', inserted_c, inserted_q;
END
$seedbody$;
